import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { TodoList, nextDue } from "../src/todo.js";

function tmpFile(content) {
  const dir = mkdtempSync(join(tmpdir(), "todo-edge-"));
  const p = join(dir, "t.json");
  if (content !== undefined) writeFileSync(p, content);
  return { p, cleanup: () => rmSync(dir, { recursive: true }) };
}

test("empty list: pending, sorted, search, byTag, clear", () => {
  const l = new TodoList();
  assert.deepEqual(l.pending(), []);
  assert.deepEqual(l.sorted(), []);
  assert.deepEqual(l.search("x"), []);
  assert.deepEqual(l.byTag("x"), []);
  l.clear();
  assert.deepEqual(l.items, []);
});

test("empty list: complete/tag on missing id throws", () => {
  const l = new TodoList();
  assert.throws(() => l.complete(1), /not found/);
  assert.throws(() => l.addTag(1, "a"), /not found/);
  assert.throws(() => l.completeAndReschedule(1), /not found/);
});

test("empty list round-trips through save/load", () => {
  const { p, cleanup } = tmpFile();
  try {
    new TodoList().save(p);
    const l = TodoList.load(p);
    assert.deepEqual(l.items, []);
    assert.equal(l.nextId, 1);
  } finally { cleanup(); }
});

test("bad titles are rejected", () => {
  const l = new TodoList();
  assert.throws(() => l.add(""), /title/);
  assert.throws(() => l.add(undefined), /title/);
  assert.throws(() => l.add("   "), /title/); // whitespace-only
});

test("bad due dates are rejected", () => {
  const l = new TodoList();
  for (const bad of ["not-a-date", "", "2024-13-45", new Date("x"), NaN, {}]) {
    assert.throws(() => l.add("t", { due: bad }), /invalid due date/, String(bad));
  }
  assert.equal(l.items.length, 0);
  assert.equal(l.nextId, 1, "failed add must not consume an id");
});

test("impossible calendar date 2024-02-30 is rejected", () => {
  const l = new TodoList();
  assert.throws(() => l.add("t", { due: "2024-02-30" }), /invalid due date/);
});

test("null/undefined due means no due date", () => {
  const l = new TodoList();
  assert.equal(l.add("a", { due: null }).due, null);
  assert.equal(l.add("b", { due: undefined }).due, null);
});

test("nextDue rejects bad input", () => {
  assert.throws(() => nextDue("garbage", "daily"), /invalid due date/);
  assert.throws(() => nextDue("2024-01-01", "yearly"), /invalid recurrence/);
});

test("invalid priority rejected", () => {
  assert.throws(() => new TodoList().add("t", { priority: "urgent" }), /invalid priority/);
  assert.throws(() => new TodoList().add("t", { priority: null }), /invalid priority/);
});

test("unicode titles survive add/search/save/load", () => {
  const { p, cleanup } = tmpFile();
  try {
    const l = new TodoList();
    const titles = ["Café ☕", "日本語のタスク", "emoji 🎉👨‍👩‍👧", "Ünïcödé ÄÖ"];
    titles.forEach(t => l.add(t));
    l.save(p);
    const l2 = TodoList.load(p);
    assert.deepEqual(l2.items.map(i => i.title), titles);
    assert.equal(l2.search("日本語").length, 1);
    assert.equal(l2.search("ÜNÏCÖDÉ").length, 1);
    assert.equal(l2.search("🎉").length, 1);
  } finally { cleanup(); }
});

test("unicode tags are normalised case-insensitively", () => {
  const l = new TodoList();
  l.add("x");
  l.addTag(1, "  ÉCOLE ");
  assert.deepEqual(l.items[0].tags, ["école"]);
  assert.equal(l.byTag("École").length, 1);
});

test("load: invalid JSON throws", () => {
  const { p, cleanup } = tmpFile("{not json");
  try { assert.throws(() => TodoList.load(p), SyntaxError); } finally { cleanup(); }
});

test("load: empty file throws", () => {
  const { p, cleanup } = tmpFile("");
  try { assert.throws(() => TodoList.load(p)); } finally { cleanup(); }
});

test("load: missing file throws", () => {
  assert.throws(() => TodoList.load(join(tmpdir(), "no-such-dir-xyz", "t.json")), /ENOENT/);
});

test("load: missing items gives a clear error (not a TypeError)", () => {
  for (const content of ["{}", '{"nextId":3}', '{"items":null}', "null", "[]", '{"items":"abc"}']) {
    const { p, cleanup } = tmpFile(content);
    try {
      assert.throws(() => TodoList.load(p), err => !(err instanceof TypeError), `content ${content}`);
    } finally { cleanup(); }
  }
});

test("load: items without id are rejected or repaired, never NaN nextId", () => {
  const { p, cleanup } = tmpFile(JSON.stringify({ nextId: 5, items: [{ title: "no id" }] }));
  try {
    let l;
    try { l = TodoList.load(p); } catch { return; } // rejecting is acceptable
    assert.ok(Number.isInteger(l.nextId), `nextId was ${l.nextId}`);
    assert.ok(l.items.every(i => Number.isInteger(i.id)), "every item needs an integer id");
  } finally { cleanup(); }
});

test("load: duplicate ids are rejected or repaired", () => {
  const { p, cleanup } = tmpFile(JSON.stringify({ nextId: 1, items: [{ id: 1, title: "a" }, { id: 1, title: "b" }] }));
  try {
    let l;
    try { l = TodoList.load(p); } catch { return; }
    assert.equal(new Set(l.items.map(i => i.id)).size, l.items.length);
  } finally { cleanup(); }
});

test("load: item without title is rejected or repaired", () => {
  const { p, cleanup } = tmpFile(JSON.stringify({ items: [{ id: 1 }] }));
  try {
    let l;
    try { l = TodoList.load(p); } catch { return; }
    assert.ok(l.items.every(i => typeof i.title === "string" && i.title));
  } finally { cleanup(); }
});

test("load: missing nextId is derived from items; defaults filled in", () => {
  const { p, cleanup } = tmpFile(JSON.stringify({ items: [{ id: 7, title: "a" }] }));
  try {
    const l = TodoList.load(p);
    assert.equal(l.nextId, 8);
    assert.equal(l.items[0].done, false);
    assert.equal(l.items[0].due, null);
    assert.equal(l.items[0].priority, "normal");
  } finally { cleanup(); }
});

test("bad ids: string, NaN, float, negative, undefined do not match", () => {
  const l = new TodoList();
  l.add("a");
  for (const bad of ["1", NaN, 1.5, -1, 0, undefined, null]) {
    assert.throws(() => l.complete(bad), /not found/, String(bad));
  }
  assert.equal(l.items[0].done, false);
});
